function cacheLookup(entry, ttl, now) {
  if (!entry) return 'miss';
  if (now - entry.savedAt < ttl) return 'hit';
  return 'stale';
}
console.log(cacheLookup({ data: 'prices', savedAt: 1000 }, 60000, 30000));

